int main(void) {
    int N, K;
    char S[200005];

    if (scanf("%d %d", &N, &K) != 2) return 0;
    if (scanf("%s", S) != 1) return 0;

    int left = 0, zero_groups = 0, ans = 0;

    for (int right = 0; right < N; right++) {
        if (S[right] == '0' && (right == 0 || S[right - 1] == '1')) {
            zero_groups++;
        }

        while (zero_groups > K) {
            if (S[left] == '0' && (left == 0 || S[left - 1] == '1')) {
                zero_groups--;
            }
            left++;
        }

        int len = right - left + 1;
        if (len > ans) ans = len;
    }

    printf("%d\n", ans);
    return 0;
}

