#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    string s;
    cin >> s;

    int ans = 0;
    int groups = 0;
    int l = 0;

    for (int r = 0; r < n; r++) {
        // Adding s[r] to window
        if (s[r] == '0') {
            // Does it start a new group?
            if (r == l || s[r-1] == '1') {
                groups++;
            }
        }

        // Shrink from left while groups > k
        while (groups > k) {
            if (s[l] == '0') {
                // removing s[l] from window
                // if s[l] is the start of a group
                if (l == r || s[l+1] == '1' || l+1 > r) {
                    // the group at l is just s[l] alone, or s[l+1] is '1'
                    // actually, removing s[l] reduces groups if s[l] starts a group
                    // s[l] starts a group if l==0 (within window, l is leftmost) or previous was '1'
                    // Since l is leftmost in window, s[l]=='0' always starts a group
                    groups--;
                }
            }
            l++;
        }

        ans = max(ans, r - l + 1);
    }

    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    string S;
    cin >> N >> K >> S;

    vector<pair<char,int>> groups;
    for (int i = 0; i < N; ) {
        int j = i;
        while (j < N && S[j] == S[i]) j++;
        groups.push_back({S[i], j - i});
        i = j;
    }

    vector<int> lens;
    if (groups[0].first == '0') lens.push_back(0);
    for (auto &g : groups) lens.push_back(g.second);
    if (groups.back().first == '0') lens.push_back(0);

    int m = lens.size();
    vector<int> pref(m + 1, 0);
    for (int i = 0; i < m; i++) pref[i + 1] = pref[i] + lens[i];

    int ans = 0;
    for (int left = 0; left < m; left += 2) {
        int right = min(m, left + 2 * K + 1);
        ans = max(ans, pref[right] - pref[left]);
    }

    cout << ans << '\n';
    return 0;
}

import java.util.Scanner;

public class MaxConsecutiveHands {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        int K = sc.nextInt();
        sc.close();

        int left = 0, zeroCount = 0, maxLen = 0;

        for (int right = 0; right < S.length(); right++) {
            if (S.charAt(right) == '0') {
                zeroCount++;
            }

            while (zeroCount > K) {
                if (S.charAt(left) == '0') {
                    zeroCount--;
                }
                left++;
            }

            maxLen = Math.max(maxLen, right - left + 1);
        }

        System.out.println(maxLen);
    }
}

