import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int K = fs.nextInt();
        String S = fs.next();

        // Run-length encode S
        ArrayList<Integer> groups = new ArrayList<>();
        ArrayList<Character> chars = new ArrayList<>();

        int cnt = 1;
        for (int i = 1; i < N; i++) {
            if (S.charAt(i) == S.charAt(i - 1)) {
                cnt++;
            } else {
                chars.add(S.charAt(i - 1));
                groups.add(cnt);
                cnt = 1;
            }
        }
        chars.add(S.charAt(N - 1));
        groups.add(cnt);

        int m = groups.size();

        // Prefix sums of group lengths
        long[] pref = new long[m + 1];
        for (int i = 0; i < m; i++) {
            pref[i + 1] = pref[i] + groups.get(i);
        }

        long ans = 0;

        // We choose a window of groups containing at most K groups of '0'
        // Since groups alternate, starting from each possible left boundary,
        // the farthest right boundary is determined by taking 2*K+1 groups,
        // adjusted by whether the left group is '0' or '1'.
        for (int l = 0; l < m; l++) {
            int r;
            if (chars.get(l) == '1') {
                r = Math.min(m, l + 2 * K + 1);
            } else {
                r = Math.min(m, l + 2 * K);
            }
            ans = Math.max(ans, pref[r] - pref[l]);
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
